--
-- Table structure for table `Products`
--

DROP TABLE IF EXISTS `Products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Products` (
  `id` int NOT NULL AUTO_INCREMENT,
  `firm_id` int NOT NULL,
  `sold_bill_id` int DEFAULT NULL,
  `created_by_user_id` int DEFAULT NULL,
  `invoice_id` int DEFAULT NULL,
  `party_id` int DEFAULT NULL,
  `invoice_product_id` int DEFAULT NULL,
  `barcode` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `barcode_type` enum('Universal','Batch','Unique') COLLATE utf8mb4_unicode_ci DEFAULT 'Unique',
  `barcode_sequence` int DEFAULT NULL,
  `batch` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `use_barcode` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `brand_id` int DEFAULT NULL,
  `category_id` int DEFAULT NULL,
  `hsnsac_code_id` int DEFAULT NULL,
  `color_id` int DEFAULT NULL,
  `department_id` int DEFAULT NULL,
  `material_id` int DEFAULT NULL,
  `size_id` int DEFAULT NULL,
  `style_id` int DEFAULT NULL,
  `sub_category_id` int DEFAULT NULL,
  `sub_style_id` int DEFAULT NULL,
  `section_id` int DEFAULT NULL,
  `product_name` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `attribute` text COLLATE utf8mb4_unicode_ci,
  `mrp` decimal(15,2) DEFAULT NULL,
  `solid_mrp` decimal(15,2) DEFAULT NULL,
  `vrp_rate` decimal(15,2) DEFAULT NULL,
  `solid_vrp_rate` decimal(15,2) DEFAULT NULL,
  `purchase_rate` decimal(15,2) DEFAULT NULL,
  `net_rate` decimal(15,2) DEFAULT NULL,
  `work_cost` decimal(15,2) DEFAULT NULL,
  `discount` decimal(15,2) DEFAULT NULL,
  `lock_discount` tinyint(1) DEFAULT '0',
  `gst` decimal(5,2) DEFAULT NULL,
  `commission_type` enum('flat','percentage') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `commission_value` decimal(15,2) DEFAULT NULL,
  `mr_commission_type` enum('flat','percentage') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mr_commission_value` decimal(15,2) DEFAULT NULL,
  `can_salesman_give_discount` tinyint(1) DEFAULT NULL,
  `is_lock_sale_rate` tinyint(1) DEFAULT NULL,
  `unit_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `unit_per_product` int DEFAULT NULL,
  `solid_unit_per_product` int DEFAULT NULL,
  `quantity` int DEFAULT '1',
  `current_stock` int DEFAULT '0',
  `is_returned` tinyint(1) DEFAULT '0',
  `is_sold` tinyint(1) DEFAULT '0',
  `location_id` int DEFAULT NULL,
  `current_location_id` int DEFAULT NULL,
  `box_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `transition_status` enum('idle','requested','approved','in-transit','delivered') COLLATE utf8mb4_unicode_ci DEFAULT 'idle',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_firm_barcode` (`firm_id`,`barcode`),
  KEY `idx_firm_is_sold` (`firm_id`,`is_sold`)
) ENGINE=InnoDB AUTO_INCREMENT=10001 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

